python3 << 'PY'
from pymatgen.io.vasp import Poscar
from pymatgen.analysis.structure_matcher import StructureMatcher
import pandas as pd

train = pd.read_csv('/work/nlo_dn_train.csv')
pool = pd.read_csv('/work/nlo_pool.csv')

def parse(s):
    return Poscar.from_str(s).structure

st = parse(pool[pool['candidate_id']=='c071'].iloc[0]['poscar'])
print('c071', st.composition, len(st), st.get_space_group_info())

for i,r in train.iterrows():
    if r['formula'] in ['In2 Cu2 Ge2 Se8','Ga2 Cu2 Ge2 Se8','Al2 Cu2 Sn2 Se8','Ga4 Hg2 Se8','Al4 Hg2 S8']:
        ts=parse(r['poscar'])
        print('\ntrain', r['formula'], len(ts), ts.get_space_group_info(), 'dn', r['dn'])
        for ltol,stol,atol in [(0.2,0.3,5),(0.4,0.6,10),(0.5,0.8,15)]:
            sm=StructureMatcher(ltol=ltol, stol=stol, angle_tol=atol, primitive_cell=True, scale=True)
            try:
                rms=sm.get_rms_dist(st, ts)
            except Exception as e:
                rms=str(e)
            print(f'  ltol={ltol} rms={rms}')

# try without species
print('\n--- anonymous matcher ---')
st_a = st.copy()
for s in st_a:
    s.species = {'X':1}
for i,r in train.iterrows():
    if r['formula'] in ['In2 Cu2 Ge2 Se8','Ga2 Cu2 Ge2 Se8','Al2 Cu2 Sn2 Se8']:
        ts=parse(r['poscar'])
        ts_a=ts.copy()
        for s in ts_a:
            s.species={'X':1}
        sm=StructureMatcher(ltol=0.3,stol=0.5,angle_tol=10)
        print(r['formula'], sm.fit(st_a, ts_a), sm.get_rms_dist(st_a, ts_a) if True else None)
